#!/bin/sh
set -eu
export XDG_RUNTIME_DIR=/run/user/$(id -u)
while IFS='=' read -r name value; do
  case "$name" in
    DISPLAY|XAUTHORITY|DBUS_SESSION_BUS_ADDRESS) export "$name=$value" ;;
    *) exit 1 ;;
  esac
done < "$XDG_RUNTIME_DIR/gbot/desktop.env"
export GTK_MODULES=gail:atk-bridge QT_ACCESSIBILITY=1 NO_AT_BRIDGE=0
export PATH=/opt/gbot/bin:$PATH
exec /opt/gbot/bin/gbot-guest "$@"
